import{_ as l,l as i,o as e,c as s,v as t,p as d,x as r,d as n,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"莫队算法","description":"","frontmatter":{"title":"莫队算法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mo-algorithm.md","filePath":"cs/mo-algorithm.md","lastUpdated":1789023840000}'),h={name:"cs/mo-algorithm.md"};function c(_,a,B,f,E,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="莫队算法" tabindex="-1">莫队算法 <a class="header-anchor" href="#莫队算法" aria-label="Permalink to &quot;莫队算法&quot;">​</a></h1><div class="epigraph"><p>区间不能随问随答时，把所有询问按左端所在块排序、块内按右端排序，让指针每次只小步扩缩。</p><footer>—— 据 Sedgewick and Wayne 对离线与分块的整理；竞赛文献中的 Mo&#39;s algorithm（莫涛）与分块排序</footer></div><p><a href="/cs/sqrt-decomposition">上一课</a>的在线分块要求「加一个点、去一个点」的代价能收进摘要。若只有「把区间从 \\([l,r]\\) 扩成 \\([l,r+1]\\)」这类 \\(\\mathrm{add}/\\mathrm{del}\\) 便宜、却没有对数树，可以把<strong>询问离线</strong>重排。本课不重定义块长。缺口是莫队：对静态数组、可加减的区间状态，用块序最小化指针移动。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(m\\) 个询问 \\([l_i,r_i]\\)，数组不变。维护当前 \\([L,R]\\) 上的状态（如不同颜色数），\\(\\mathrm{add}(i)\\)、\\(\\mathrm{del}(i)\\) 为 \\(O(1)\\) 或 \\(O(\\log n)\\)。若按输入顺序跳，指针总移动可到 \\(\\Theta(nm)\\)。莫队：块大小 \\(B\\)，询问按 \\((\\lfloor l/B\\rfloor,\\, r)\\) 排序（偶数块 \\(r\\) 反转可再省常数）。相邻询问的 \\(L,R\\) 变化合计 \\(O(n\\sqrt{m})\\) 量级（\\(m\\sim n\\)、\\(B\\sim n/\\sqrt{m}\\) 时常见 \\(O(n\\sqrt{n})\\)）。缺口不是新状态机，而是<strong>离线重排降低扩缩次数</strong>。</p><p><span class="marginnote">名称来自莫涛对分块排序技巧的普及。奇偶块翻转右端，减少块间 \\(R\\) 来回扫，是同一分析下的常数优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读入全部询问，排序，从空或任意区间出发，对每个询问 while 扩缩 \\(L,R\\) 到目标，再记录答案。必须能逆：扩与缩都要正确，不能只 add 不能 del。</p>',8)),(e(),d(p,null,{default:r(()=>[m(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22%E7%A6%BB%E7%BA%BF%E5%85%A8%E9%83%A8%20%5Bl%2C%20r%5D%22%5D%20--%3E%20SORT%5B%22%E6%8C%89%E5%B7%A6%E5%9D%97%2C%20%E5%86%8D%E6%8C%89%20r%22%5D%0A%20%20SORT%20--%3E%20PTR%5B%22%E6%8C%87%E9%92%88%20L%2C%20R%20%E6%89%A9%E7%BC%A9%22%5D%0A%20%20PTR%20--%3E%20ADD%5B%22add%20%2F%20del%20%E7%BB%B4%E6%8A%A4%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>带修改莫队多一维时间块，复杂度更高，本课只钉静态。树上莫队把欧拉序当序列，机制仍是扩缩，本课不写。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分析：左端每次询问最多动 \\(O(B)\\)，共 \\(O(mB)\\)；右端在同一块内单调，块间重置，共 \\(O(n\\cdot n/B)\\) 一类界。取 \\(B\\approx n/\\sqrt{m}\\) 平衡。这是<a href="/cs/amortized-analysis">摊还</a>合计，不是单次询问对数。</p><p>状态必须是「区间的可加减函数」。中位数若不能 \\(O(1)\\) add/del，莫队帮不上，应换权值树或排序分块。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>在线算法不能用莫队（必须先收齐询问）。不可逆状态、强制在线、或修改穿插过多时退回树。不要把莫队写成「所有区间问题的默认解」。</p><p>区间查询课序还剩紧凑的位级集合表示：位图与稀疏集合，不是再一张排序表。</p><p>后课默认：静态离线、状态可加减，可按块序扩缩。位级并行的集合用 bitset。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>莫队：离线按块排序，指针扩缩均摊近 \\(O(n\\sqrt{n})\\)。</li><li>要 add 与 del；数组静态。</li><li>位级集合是下一结构，不是另一套莫队。</li><li>出处：分块排序技巧；Sedgewick and Wayne；莫队作为该技巧的通行名。</li></ul>',10))])}const q=l(h,[["render",c]]);export{T as __pageData,q as default};
